async function reviewedSlotOpener(document, section) {
  const root = gameRoot(document.fileName);
  let target = null;
  if (root) {
    const projectContext = require('./project_context_ui');
    const loaded = projectContext.readRegistry(root);
    if (loaded.exists && !loaded.issues?.some(issue => issue.level === 'error')) {
      const context = require('./project_context_model').contextFor(document.fileName, root, loaded.registry);
      if (context.project?.engineTarget) target = context.project.engineTarget;
    }
  }
  const loaderFile = root && path.join(root, 'external', 'script', 'main.lua');
  const loaderSource = loaderFile && fs.existsSync(loaderFile) ? fs.readFileSync(loaderFile, 'utf8') : '';
  if (section === 'extrastages' && !supportsStageSlots(loaderSource)) {
    vscode.window.showWarningMessage('This engine loader does not prove support for [ExtraStages] slot groups. IKEMEN GO 1.0.0 reads stage lines individually. Keep stages as separate lines or select a compatible engine.');
    return null;
  }
  let opener = slotSyntaxForTarget(target, document.getText(), section, loaderSource);
  if (!opener) {
    const picked = await vscode.window.showQuickPick([
      { label: 'Current Nightly · slot {', opener: 'slot {' },
      { label: 'IKEMEN GO 1.0.0 · slot = {', opener: 'slot = {' }
    ], { title: 'Choose the engine syntax for this roster slot', placeHolder: 'No pinned target or consistent existing slot syntax was found.' });
    if (!picked) return null;
    opener = picked.opener;
  }
  const conflicting = parseSelectDef(document.getText()).entries.filter(entry => entry.kind === 'slot-start' && entry.section === section && (entry.code.includes('=') ? 'slot = {' : 'slot {') !== opener);
  const detail = `The source line and its comments are preserved. The opener follows the pinned engine loader or your selected syntax.${conflicting.length ? `\n\n${conflicting.length} existing [${section}] slot opener(s) use the other syntax. They remain unchanged; review them in the text editor because this engine may ignore them.` : ''}`;
  const approved = await vscode.window.showWarningMessage(`Wrap this [${section}] entry in ${opener} ... }?`, { modal: true, detail }, 'Create Slot');
  return approved === 'Create Slot' ? opener : null;
}

