function fitViewport(force=false){const viewport=$('screenViewport'),frame=$('screenFrame');if(!viewport||!frame)return;const aspect=m.localCoord[0]/m.localCoord[1],base=Math.max(240,Math.min(viewport.clientWidth-4,(viewport.clientHeight-4)*aspect));if(force)zoom=1;frame.style.width=(base*zoom)+'px';frame.style.height=(base*zoom/aspect)+'px';const label=$('zoomLabel');if(label&&document.activeElement!==label)label.textContent=Math.round(zoom*100)+'%';saveState({tab,page,inventoryTab,zoom,showCellNames,showCellNumbers})}
function face(cell){faceCtx.clearRect(0,0,faces.width,faces.height);if(!cell)return;const pair=p.largePortraits?.[cell.id];if(!pair)return;for(const side of ['p1','p2']){const portrait=pair[side],spec=m.faceSpecs?.[side];if(!portrait||portrait.state!=='ready'||!spec)continue;const image=new Image();image.onload=()=>{faceCtx.save();faceCtx.translate(spec.offset[0],spec.offset[1]);faceCtx.scale(spec.facing*spec.scale[0],spec.scale[1]);faceCtx.drawImage(image,-portrait.axisX,-portrait.axisY);faceCtx.restore()};image.src=portrait.src}}
