async function reveal(document, line) { const editor = await vscode.window.showTextDocument(document, { viewColumn: vscode.ViewColumn.One, preview: false }); const target = Math.max(0, Math.min(document.lineCount - 1, line)); editor.selection = new vscode.Selection(target, 0, target, 0); editor.revealRange(new vscode.Range(target, 0, target, 0), vscode.TextEditorRevealType.InCenter); }
