async function scanInstalled(folder,options,title){
  const run=async(progress,token)=>require('./async_discovery').discover(folder,{...options,token,onProgress:count=>progress?.report({message:count+' folders scanned'})});
  const result=vscode.window.withProgress?await vscode.window.withProgress({location:vscode.ProgressLocation.Notification,title,cancellable:true},run):await run();
  if(result.cancelled)return null;
  if(result.errors.length)await vscode.window.showWarningMessage(result.errors.length+' files or folders could not be read while scanning. Available results are still shown.');
  return result.files;
}
async function installedCharacters(document, model) {
  const root=gameRoot(document.fileName),chars=root&&path.join(root,'chars');
  if(!chars||!fs.existsSync(chars))return[];
  const found=await scanInstalled(chars,{maxDepth:4,extensions:['.def'],accept:async file=>{const text=await fs.promises.readFile(file,'utf8');return /^\s*\[\s*Info\s*\]/im.test(text)&&/^\s*(?:name|displayname)\s*=/im.test(text);}},'Finding installed characters');
  if(!found)return null;
  const existing=new Set(model.characters.map(entry=>String(entry.name).replace(/^chars[\\/]/i,'').replace(/\\/g,'/').toLowerCase()));
  return found.map(full=>({full,reference:path.relative(chars,full).replace(/\\/g,'/')})).filter(item=>!existing.has(item.reference.toLowerCase())&&!existing.has(item.reference.replace(/\.def$/i,'').toLowerCase())).sort((a,b)=>a.reference.localeCompare(b.reference,undefined,{numeric:true}));
}
async function installedStages(document,model){
  const root=gameRoot(document.fileName),stages=root&&path.join(root,'stages');
  if(!stages||!fs.existsSync(stages))return[];
  const found=await scanInstalled(stages,{maxDepth:5,extensions:['.def','.zip']},'Finding installed stages');
  if(!found)return null;
  const existing=new Set(model.stages.map(entry=>String(entry.positional[0]||entry.name).replace(/\\/g,'/').toLowerCase()));
  return found.map(full=>({full,reference:path.relative(root,full).replace(/\\/g,'/')})).filter(item=>!existing.has(item.reference.toLowerCase())).sort((a,b)=>a.reference.localeCompare(b.reference,undefined,{numeric:true}));
}
function slotBounds(model, line) {
  let start = -1, end = -1;
  const section = model.entries.find(item => item.line === line)?.section;
  if (!['characters', 'extrastages'].includes(section)) return null;
  for (const entry of model.entries.filter((item) => item.section === section)) {
    if (entry.kind === 'slot-start') { start = entry.line; end = -1; }
    else if (entry.kind === 'slot-end' && start >= 0) { end = entry.line; if (line >= start && line <= end) return { start, end }; start = -1; }
  }
  return null;
}
function replaceCharacterStages(entry, stages) { const pieces = [entry.positional[0], ...stages, ...entry.params.map((item) => `${item.name}=${item.value}`)]; return pieces.filter(Boolean).join(', '); }
function replaceParameter(entry, name, value) { const params = entry.params.map((item) => item.name.toLowerCase() === name.toLowerCase() ? { ...item, value } : item); if (!params.some((item) => item.name.toLowerCase() === name.toLowerCase()) && value) params.push({ name, value }); return [...entry.positional, ...params.filter((item) => item.value !== '').map((item) => `${item.name}=${item.value}`)].join(', '); }
async function replaceMany(document, entries, transform) {
  const edit = new vscode.WorkspaceEdit();
  for (const entry of entries) edit.replace(document.uri, document.lineAt(entry.line).range, transform(entry));
  return entries.length ? vscode.workspace.applyEdit(edit) : false;
}
